package dev.mineagent.runtime.neoforge.client.nativeui;
import com.google.gson.*;import com.lowdragmc.lowdraglib2.gui.ui.*;import com.lowdragmc.lowdraglib2.gui.ui.elements.*;import net.minecraft.client.Minecraft;import net.minecraft.client.gui.screens.Screen;import net.minecraft.network.chat.Component;import java.util.*;
public final class ModelCapabilitiesScreen extends NativeInputScreen {
 private final Screen parent;private final String agent,model;private final TextElement status=WorkspacePanels.text("");private final Selector<Choice> vision=new Selector<>(),tools=new Selector<>();private final TextField context=new TextField();private final Toggle capture=new Toggle();private long revision;private boolean busy;
 private record Choice(String id,String label){public String toString(){return label;}}
 public static void open(String agent,String model){var mc=Minecraft.getInstance();mc.setScreen(new ModelCapabilitiesScreen(mc.screen,agent,model,new UIElement()));}
 private ModelCapabilitiesScreen(Screen parent,String agent,String model,UIElement root){super(new ModularUI(NativeUiTheme.ui(root),Minecraft.getInstance().player),Component.literal(t("模型能力与截图")));this.parent=parent;this.agent=agent;this.model=model;
  root.getLayout().widthPercent(100).heightPercent(100).paddingAll(8);var card=NativeUiTheme.card(new UIElement());card.getLayout().widthPercent(100).heightPercent(100);root.addChild(card);card.addChild(WorkspacePanels.text(t("模型能力与截图")+" · "+model));card.addChild(status);var scroll=WorkspacePanels.scroller(card);scroll.getLayout().minHeight(0);
  for(var pair:List.of(new AbstractMap.SimpleEntry<>(t("视觉输入"),vision),new AbstractMap.SimpleEntry<>(t("工具调用"),tools))){var row=WorkspacePanels.card(scroll,pair.getKey());var selector=pair.getValue();NativeUiTheme.options(selector);selector.setCandidates(List.of(new Choice("UNKNOWN",t("尚未确认")),new Choice("YES",t("支持")),new Choice("NO",t("不支持"))));selector.setValue(selector.getCandidates().getFirst(),false);selector.getLayout().widthPercent(100).height(25);row.addChild(selector);}
  var length=WorkspacePanels.card(scroll,t("上下文长度（0 表示未知）"));context.setText("0",false);context.getLayout().widthPercent(100).height(24);length.addChild(context);var snapshots=WorkspacePanels.card(scroll,t("可选游戏截图"));capture.setText(t("允许 AI 查看本世界／服务器的游戏画面"));capture.setOn(ResourceCapturePreference.allowed(),false);snapshots.addChild(capture);snapshots.addChild(WorkspacePanels.text(t("只截取 Minecraft；密钥界面不会截图。")));
  var probes=WorkspacePanels.row();probes.getLayout().heightAuto().minHeight(26);scroll.addScrollViewChild(probes);probes.addChild(NativeUiTheme.button(t("探测视觉能力"),()->probe("vision")));probes.addChild(NativeUiTheme.button(t("探测工具调用"),()->probe("tools")));scroll.addScrollViewChild(WorkspacePanels.text(t("探测会向当前模型服务发送一次小型测试请求。")));var actions=WorkspacePanels.row();actions.getLayout().height(26);card.addChild(actions);actions.addChild(NativeUiTheme.button(t("保存"),this::save));actions.addChild(NativeUiTheme.button(t("返回"),this::onClose));read();
 }
 private boolean current(){return Minecraft.getInstance().screen==this;}
 private void load(JsonObject value){revision=value.get("revision").getAsLong();for(var entry:List.of(new AbstractMap.SimpleEntry<>(vision,"vision"),new AbstractMap.SimpleEntry<>(tools,"tools")))for(var c:entry.getKey().getCandidates())if(c.id().equals(value.get(entry.getValue()).getAsString()))entry.getKey().setValue(c,false);context.setText(value.get("contextTokens").getAsString(),false);status.setText(Component.literal(t("能力来源：")+t(switch(value.get("source").getAsString()){case "METADATA"->"服务目录";case "MANUAL"->"手动设置";case "PROBE"->"实际探测";default->"尚未确认";})));}
 private void read(){busy=true;WorkspacePanels.request("agent.modelCapabilityRead",Map.of("agentId",agent,"model",model)).whenComplete((receipt,error)->{busy=false;if(!current())return;if(error!=null){WorkspacePanels.failure(status,error);return;}load(WorkspacePanels.state(receipt));});}
 private void probe(String kind){if(busy)return;busy=true;status.setText(Component.literal(t("正在探测模型能力…")));WorkspacePanels.request("agent.modelCapabilityProbe",Map.of("agentId",agent,"model",model,"capability",kind)).whenComplete((receipt,error)->{busy=false;if(!current())return;if(error!=null){WorkspacePanels.failure(status,error);return;}var value=WorkspacePanels.state(receipt);load(value);if(value.has("probe")&&!value.get("probe").getAsString().equals("PASSED"))status.setText(Component.literal(t("未取得有效证据，保留原设置。")));});}
 private void save(){if(busy)return;try{int count=Integer.parseInt(context.getValue());if(count<0||count>16777216)throw new IllegalArgumentException();busy=true;WorkspacePanels.request("agent.modelCapabilitySave",Map.of("agentId",agent,"model",model,"expectedRevision",Long.toString(revision),"vision",vision.getValue().id(),"tools",tools.getValue().id(),"contextTokens",Integer.toString(count),"screenshots",Boolean.toString(capture.isOn()))).whenComplete((receipt,error)->{busy=false;if(!current())return;if(error!=null){WorkspacePanels.failure(status,error);return;}try{ResourceCapturePreference.set(capture.isOn());load(WorkspacePanels.state(receipt));status.setText(Component.literal(t("已保存")));}catch(Exception e){WorkspacePanels.failure(status,e);}});}catch(Exception e){status.setText(Component.literal(t("上下文长度需要填写有效整数。")));}}
 @Override public void onClose(){Minecraft.getInstance().setScreen(parent);}
 private static String t(String text){return dev.mineagent.runtime.neoforge.client.language.ClientLanguage.t(text);}
}
